-- Closed migration provenance. No backfill, automatic promotion, credential or Main activation.
ALTER TABLE legacy_migration_publication_decisions ADD CONSTRAINT legacy_migration_decision_owner UNIQUE(decision_id,identity_id);
CREATE TABLE legacy_migration_verified_final_acks (
 decision_id uuid PRIMARY KEY,identity_id uuid NOT NULL,migration_id uuid NOT NULL UNIQUE REFERENCES legacy_migration_intents(id),
 stage_operation_id uuid NOT NULL,publication_command_id uuid NOT NULL UNIQUE,profile_id uuid NOT NULL,
 protocol_version integer NOT NULL CHECK(protocol_version=1),baseline_generation bigint NOT NULL CHECK(baseline_generation>0),contact_mutation_revision bigint NOT NULL CHECK(contact_mutation_revision>=0),
 publication_revision bigint NOT NULL CHECK(publication_revision=1),email_contact_version bigint NOT NULL CHECK(email_contact_version>0),
 email_receipt_id uuid NOT NULL REFERENCES legacy_migration_otp_receipts(id),email_receipt_generation bigint NOT NULL CHECK(email_receipt_generation>0),phone_receipt_id uuid NOT NULL REFERENCES legacy_migration_otp_receipts(id),phone_receipt_generation bigint NOT NULL CHECK(phone_receipt_generation>0),
 baseline_hash text NOT NULL CHECK(baseline_hash~'^[0-9a-f]{64}$'),stage_ack_hash text NOT NULL CHECK(stage_ack_hash~'^[0-9a-f]{64}$'),receipt_snapshot_hash text NOT NULL CHECK(receipt_snapshot_hash~'^[0-9a-f]{64}$'),payload_hash text NOT NULL CHECK(payload_hash~'^[0-9a-f]{64}$'),final_ack_hash text NOT NULL CHECK(final_ack_hash~'^[0-9a-f]{64}$'),journal_hash text NOT NULL CHECK(journal_hash~'^[0-9a-f]{64}$'),provenance_hash text NOT NULL CHECK(provenance_hash~'^[0-9a-f]{64}$'),
 retention_key_id varchar(32) NOT NULL CHECK(retention_key_id~'^[A-Za-z0-9_-]{1,32}$'),ack_json text NOT NULL CHECK(octet_length(ack_json)<=12288),verified_at timestamptz NOT NULL,
 UNIQUE(decision_id,identity_id),FOREIGN KEY(decision_id,identity_id) REFERENCES legacy_migration_publication_decisions(decision_id,identity_id),CHECK(email_receipt_id<>phone_receipt_id)
);
CREATE TABLE legacy_migration_final_commands (
 decision_id uuid PRIMARY KEY,identity_id uuid NOT NULL,migration_id uuid NOT NULL UNIQUE,final_command_id uuid NOT NULL UNIQUE,actor_id varchar(64) NOT NULL CHECK(actor_id~'^[A-Za-z0-9_-]{1,64}$'),
 retention_key_id varchar(32) NOT NULL CHECK(retention_key_id~'^[A-Za-z0-9_-]{1,32}$'),ack_provenance_hash text NOT NULL CHECK(ack_provenance_hash~'^[0-9a-f]{64}$'),journal_hash text NOT NULL CHECK(journal_hash~'^[0-9a-f]{64}$'),command_hash bytea NOT NULL CHECK(octet_length(command_hash)=32),classification_generation bigint NOT NULL CHECK(classification_generation>0),
 original_owner_generation bigint NOT NULL CHECK(original_owner_generation>=0),original_mode_generation bigint NOT NULL CHECK(original_mode_generation>=0),original_email_generation bigint NOT NULL CHECK(original_email_generation>=0),original_account_deadline timestamptz NOT NULL,original_intent_deadline timestamptz NOT NULL,created_at timestamptz NOT NULL,
 UNIQUE(decision_id,final_command_id),FOREIGN KEY(decision_id,identity_id) REFERENCES legacy_migration_publication_decisions(decision_id,identity_id),FOREIGN KEY(decision_id,identity_id) REFERENCES legacy_migration_verified_final_acks(decision_id,identity_id),CHECK(created_at<original_account_deadline AND created_at<original_intent_deadline)
);
CREATE TABLE managed_identity_sources (
 identity_id uuid PRIMARY KEY REFERENCES identities(id),source_kind varchar(40) NOT NULL CHECK(source_kind IN ('REGISTRATION_DUAL_CONTACT','LEGACY_MIGRATION_DUAL_CONTACT')),source_id uuid NOT NULL,classification_generation bigint NOT NULL CHECK(classification_generation>0),registration_enrollment_id uuid,migration_decision_id uuid,created_at timestamptz NOT NULL,
 UNIQUE(source_kind,source_id),UNIQUE(identity_id,source_kind,source_id,classification_generation),
 FOREIGN KEY(identity_id,registration_enrollment_id) REFERENCES managed_registration_principals(identity_id,enrollment_id),FOREIGN KEY(migration_decision_id,identity_id) REFERENCES legacy_migration_verified_final_acks(decision_id,identity_id),
 CHECK((source_kind='REGISTRATION_DUAL_CONTACT' AND registration_enrollment_id=source_id AND registration_enrollment_id IS NOT NULL AND migration_decision_id IS NULL) OR(source_kind='LEGACY_MIGRATION_DUAL_CONTACT' AND migration_decision_id=source_id AND migration_decision_id IS NOT NULL AND registration_enrollment_id IS NULL))
);
CREATE TABLE migration_banking_authorities (
 identity_id uuid NOT NULL,decision_id uuid NOT NULL,migration_id uuid NOT NULL,issuer varchar(512) NOT NULL,subject varchar(255) NOT NULL,
 source_kind varchar(40) NOT NULL DEFAULT 'LEGACY_MIGRATION_DUAL_CONTACT' CHECK(source_kind='LEGACY_MIGRATION_DUAL_CONTACT'),classification_generation bigint NOT NULL CHECK(classification_generation>0),state varchar(16) NOT NULL CHECK(state IN ('ACTIVE','SUSPENDED')),verification_epoch bigint NOT NULL CHECK(verification_epoch>0),source_revision bigint NOT NULL CHECK(source_revision>0),policy_version bigint NOT NULL CHECK(policy_version>0),
 original_owner_generation bigint NOT NULL CHECK(original_owner_generation>=0),post_cutover_owner_generation bigint NOT NULL CHECK(post_cutover_owner_generation>=0),original_mode_generation bigint NOT NULL CHECK(original_mode_generation>=0),current_mode_generation bigint NOT NULL CHECK(current_mode_generation>=0),association_generation bigint NOT NULL CHECK(association_generation>=0),
 email_source varchar(32) NOT NULL CHECK(email_source IN ('CREDENTIAL_EMAIL','MIGRATION_OWNER_CONTACT','ABSENT_OWNER_CONTACT')),email_baseline_generation bigint NOT NULL CHECK(email_baseline_generation>=0),email_baseline_digest text,candidate_id uuid,candidate_version bigint CHECK(candidate_version=1),candidate_digest text,contact_transition_hash text,verified_contact_generation bigint CHECK(verified_contact_generation>0),
 canonical_email varchar(254) NOT NULL,canonical_phone varchar(13) NOT NULL,email_receipt_id uuid NOT NULL REFERENCES legacy_migration_otp_receipts(id),phone_receipt_id uuid NOT NULL REFERENCES legacy_migration_otp_receipts(id),email_receipt_generation bigint NOT NULL CHECK(email_receipt_generation>0),phone_receipt_generation bigint NOT NULL CHECK(phone_receipt_generation>0),
 stage_operation_id uuid NOT NULL,stage_ack_hash text NOT NULL,final_ack_hash text NOT NULL,receipt_snapshot_hash text NOT NULL,publication_revision bigint NOT NULL CHECK(publication_revision=1),journal_hash text NOT NULL,immutable_provenance_hash bytea NOT NULL CHECK(octet_length(immutable_provenance_hash)=32),
 user_baseline_generation bigint NOT NULL CHECK(user_baseline_generation>0),user_contact_mutation_revision bigint NOT NULL CHECK(user_contact_mutation_revision>=0),projection_present boolean NOT NULL,user_projection_revision bigint,user_phone_contact_version bigint,user_verification_epoch bigint,email_contact_version bigint NOT NULL CHECK(email_contact_version>0),email_digest text NOT NULL,
 created_at timestamptz NOT NULL,version_created_at timestamptz NOT NULL,suspension_reason varchar(32),
 PRIMARY KEY(identity_id,decision_id,verification_epoch,source_revision),
 FOREIGN KEY(decision_id,identity_id) REFERENCES legacy_migration_publication_decisions(decision_id,identity_id),FOREIGN KEY(decision_id,identity_id) REFERENCES legacy_migration_verified_final_acks(decision_id,identity_id),FOREIGN KEY(identity_id,source_kind,decision_id,classification_generation) REFERENCES managed_identity_sources(identity_id,source_kind,source_id,classification_generation),
 CHECK(email_receipt_id<>phone_receipt_id),CHECK((projection_present AND user_projection_revision>0 AND user_phone_contact_version>0 AND user_verification_epoch>0 AND user_projection_revision IS NOT NULL AND user_phone_contact_version IS NOT NULL AND user_verification_epoch IS NOT NULL) OR(NOT projection_present AND user_projection_revision IS NULL AND user_phone_contact_version IS NULL AND user_verification_epoch IS NULL)),
 CHECK((email_source='ABSENT_OWNER_CONTACT' AND email_baseline_generation=0 AND email_baseline_digest IS NULL AND candidate_id IS NOT NULL AND candidate_version=1 AND candidate_digest IS NOT NULL AND contact_transition_hash IS NOT NULL AND verified_contact_generation IS NOT NULL) OR(email_source='MIGRATION_OWNER_CONTACT' AND email_baseline_generation>0 AND email_baseline_digest IS NOT NULL AND candidate_id IS NOT NULL AND candidate_version=1 AND candidate_digest IS NOT NULL) OR(email_source='CREDENTIAL_EMAIL' AND email_baseline_generation>0 AND email_baseline_digest IS NOT NULL AND candidate_id IS NULL AND candidate_version IS NULL AND candidate_digest IS NULL AND contact_transition_hash IS NULL AND verified_contact_generation IS NULL)),
 CHECK((state='ACTIVE' AND suspension_reason IS NULL) OR(state='SUSPENDED' AND suspension_reason IS NOT NULL))
);
CREATE TABLE migration_banking_authority_current (
 identity_id uuid PRIMARY KEY,decision_id uuid NOT NULL UNIQUE,migration_id uuid NOT NULL UNIQUE,issuer varchar(512) NOT NULL,subject varchar(255) NOT NULL,classification_generation bigint NOT NULL CHECK(classification_generation>0),current_epoch bigint NOT NULL CHECK(current_epoch>0),current_source_revision bigint NOT NULL CHECK(current_source_revision>0),UNIQUE(issuer,subject),
 FOREIGN KEY(identity_id,decision_id,current_epoch,current_source_revision) REFERENCES migration_banking_authorities(identity_id,decision_id,verification_epoch,source_revision)
);
CREATE TABLE migration_banking_grants (
 identity_id uuid NOT NULL,verification_epoch bigint NOT NULL CHECK(verification_epoch>0),decision_id uuid NOT NULL,classification_generation bigint NOT NULL CHECK(classification_generation>0),source_revision bigint NOT NULL CHECK(source_revision>0),policy_version bigint NOT NULL CHECK(policy_version>0),immutable_provenance_hash bytea NOT NULL CHECK(octet_length(immutable_provenance_hash)=32),created_at timestamptz NOT NULL,
 PRIMARY KEY(identity_id,verification_epoch),FOREIGN KEY(identity_id,decision_id,verification_epoch,source_revision) REFERENCES migration_banking_authorities(identity_id,decision_id,verification_epoch,source_revision)
);
CREATE TABLE legacy_migration_final_completions (
 decision_id uuid PRIMARY KEY,identity_id uuid NOT NULL,migration_id uuid NOT NULL UNIQUE,source_kind varchar(40) NOT NULL CHECK(source_kind='LEGACY_MIGRATION_DUAL_CONTACT'),source_id uuid NOT NULL,classification_generation bigint NOT NULL CHECK(classification_generation>0),resulting_owner_generation bigint NOT NULL CHECK(resulting_owner_generation>=0),resulting_mode_generation bigint NOT NULL CHECK(resulting_mode_generation>=0),association_generation bigint NOT NULL CHECK(association_generation>=0),source_revision bigint NOT NULL CHECK(source_revision>0),verification_epoch bigint NOT NULL CHECK(verification_epoch>0),authority_stamp bytea NOT NULL CHECK(octet_length(authority_stamp)=32),final_ack_hash text NOT NULL,receipt_snapshot_hash text NOT NULL,journal_hash text NOT NULL,provenance_hash text NOT NULL,retention_key_id varchar(32) NOT NULL,final_command_id uuid NOT NULL UNIQUE,final_command_hash bytea NOT NULL CHECK(octet_length(final_command_hash)=32),completed_at timestamptz NOT NULL,completion_json text NOT NULL CHECK(octet_length(completion_json)<=12288),
 UNIQUE(decision_id,identity_id),FOREIGN KEY(decision_id,identity_id) REFERENCES legacy_migration_publication_decisions(decision_id,identity_id),FOREIGN KEY(decision_id,identity_id) REFERENCES legacy_migration_verified_final_acks(decision_id,identity_id),FOREIGN KEY(identity_id,decision_id,verification_epoch,source_revision) REFERENCES migration_banking_authorities(identity_id,decision_id,verification_epoch,source_revision),FOREIGN KEY(decision_id,final_command_id) REFERENCES legacy_migration_final_commands(decision_id,final_command_id),CHECK(source_id=decision_id)
);
CREATE FUNCTION migration_authority_pointer_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE prior migration_banking_authorities; successor migration_banking_authorities;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'permanent migration authority pointer' USING ERRCODE='23514'; END IF;
 IF NEW.identity_id<>OLD.identity_id OR NEW.decision_id<>OLD.decision_id OR NEW.migration_id<>OLD.migration_id OR NEW.issuer<>OLD.issuer OR NEW.subject<>OLD.subject OR NEW.classification_generation<>OLD.classification_generation THEN RAISE EXCEPTION 'immutable migration source' USING ERRCODE='23514'; END IF;
 SELECT * INTO STRICT prior FROM migration_banking_authorities WHERE identity_id=OLD.identity_id AND decision_id=OLD.decision_id AND verification_epoch=OLD.current_epoch AND source_revision=OLD.current_source_revision;
 SELECT * INTO STRICT successor FROM migration_banking_authorities WHERE identity_id=NEW.identity_id AND decision_id=NEW.decision_id AND verification_epoch=NEW.current_epoch AND source_revision=NEW.current_source_revision;
 IF prior.state<>'ACTIVE' OR successor.state<>'SUSPENDED' OR NEW.current_epoch<>OLD.current_epoch+1 OR NEW.current_source_revision<>OLD.current_source_revision+1 OR (to_jsonb(prior)-ARRAY['state','verification_epoch','source_revision','version_created_at','suspension_reason'])<>(to_jsonb(successor)-ARRAY['state','verification_epoch','source_revision','version_created_at','suspension_reason']) THEN RAISE EXCEPTION 'invalid migration authority transition' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER migration_authority_pointer_transition BEFORE UPDATE OR DELETE ON migration_banking_authority_current FOR EACH ROW EXECUTE FUNCTION migration_authority_pointer_guard();
CREATE TRIGGER legacy_migration_verified_final_acks_immutable BEFORE UPDATE OR DELETE ON legacy_migration_verified_final_acks FOR EACH ROW EXECUTE FUNCTION legacy_migration_foundation_immutable();
CREATE TRIGGER legacy_migration_final_commands_immutable BEFORE UPDATE OR DELETE ON legacy_migration_final_commands FOR EACH ROW EXECUTE FUNCTION legacy_migration_foundation_immutable();
CREATE TRIGGER managed_identity_sources_immutable BEFORE UPDATE OR DELETE ON managed_identity_sources FOR EACH ROW EXECUTE FUNCTION legacy_migration_foundation_immutable();
CREATE TRIGGER migration_banking_authorities_immutable BEFORE UPDATE OR DELETE ON migration_banking_authorities FOR EACH ROW EXECUTE FUNCTION legacy_migration_foundation_immutable();
CREATE TRIGGER migration_banking_grants_immutable BEFORE UPDATE OR DELETE ON migration_banking_grants FOR EACH ROW EXECUTE FUNCTION legacy_migration_foundation_immutable();
CREATE TRIGGER legacy_migration_final_completions_immutable BEFORE UPDATE OR DELETE ON legacy_migration_final_completions FOR EACH ROW EXECUTE FUNCTION legacy_migration_foundation_immutable();
