CREATE FUNCTION migration_source_metadata_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF ROW(NEW.eligibility_source,NEW.eligibility_source_id,NEW.classification_generation,NEW.source_revision,NEW.source_stamp,NEW.migration_decision_id,NEW.migration_email_receipt_generation,NEW.migration_phone_receipt_generation,NEW.migration_verified_contact_generation) IS DISTINCT FROM ROW(OLD.eligibility_source,OLD.eligibility_source_id,OLD.classification_generation,OLD.source_revision,OLD.source_stamp,OLD.migration_decision_id,OLD.migration_email_receipt_generation,OLD.migration_phone_receipt_generation,OLD.migration_verified_contact_generation) THEN RAISE EXCEPTION 'immutable native eligibility source' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER sso_login_events_eligibility_source_immutable BEFORE UPDATE ON sso_login_events FOR EACH ROW EXECUTE FUNCTION migration_source_metadata_immutable();
